CREATE COLUMN TABLE "TEST_AP"."ECM1" ("Code" NVARCHAR(8) NOT NULL , "LineNum" INTEGER CS_INT NOT NULL , "StrIndex" SMALLINT CS_INT, "BPLId" INTEGER CS_INT DEFAULT -1 NOT NULL , "ParamType" NVARCHAR(2) DEFAULT 'TX', "ParamVisib" NVARCHAR(1) DEFAULT 'Y', "ParamName" NVARCHAR(100) NOT NULL , "ParamValue" NCLOB MEMORY THRESHOLD 1000, "UserSign" SMALLINT CS_INT, "CreateDate" LONGDATE CS_LONGDATE, "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "LogInstanc" SMALLINT CS_INT, "ParamPrms" NVARCHAR(254), "UIorder" SMALLINT CS_INT, "Type" SMALLINT CS_INT, PRIMARY KEY ("Code", "BPLId", "LineNum")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "ECM1_PARAM_NAME" ON "TEST_AP"."ECM1" ( "Code" ASC, "BPLId" ASC, "ParamName" ASC )